import com.mbeddr.mpsutil.interpreter.rt.ComputationTrace;
import com.mbeddr.mpsutil.interpreter.rt.InterpreterRuntimeException;
import com.mbeddr.mpsutil.interpreter.rt.InterpreterEscapeException;
import org.jetbrains.mps.openapi.model.SNode;

public class TraceFailures {

  public static ComputationTrace markFailure(Throwable t) {
    // Locates the trace record of the node whose evaluation threw t and marks it as the failure,
    // so that the trace explorer renders it in red and its filters do not drop it.
    // The interpreter wraps whatever escapes an evaluator into an InterpreterRuntimeException that
    // knows the node and its trace record, and every enclosing evaluator wraps that again, so the
    // record of the node that actually threw is the last one along the cause chain.
    // Returns null if t carries no trace record at all.
    ComputationTrace failing = null;
    Throwable current = t;
    while (current != null) {
      ComputationTrace candidate = null;
      if (current instanceof InterpreterRuntimeException) {
        candidate = ((InterpreterRuntimeException) current).getFailureTrace();
      } else if (current instanceof InterpreterEscapeException) {
        candidate = ((InterpreterEscapeException) current).failedTrace;
      }
      if (candidate != null) {
        failing = candidate;
      }
      current = ((current.getCause() == current ? null : current.getCause()));
    }
    if (failing == null) {
      return null;
    }
    if (!(failing.hasConstraintFailure())) {
      failing.setConstraintFailure(describe(t));
    }
    failing.unmarkAsShowNever();
    failing.markAsShowInAnyCase();
    failing.markForReveal();
    return failing;
  }

  public static ComputationTrace traceForFailure(SNode fallbackNode, ComputationTrace partialTrace, Throwable t) {
    // The root trace to show after t has aborted an evaluation; never null.
    // Everything that was computed before the exception is already in the trace, because the record
    // for a node is added to its parent before that node is evaluated. So the partial trace is worth
    // showing even though the exception unwound the evaluation.
    ComputationTrace failing = markFailure(t);
    ComputationTrace root = null;
    if (partialTrace != null) {
      root = partialTrace.rootTrace();
    } else
    if (failing != null) {
      root = failing.rootTrace();
    }
    if (root == null) {
      // The interpreter did not get far enough to build a trace: show the failure by itself.
      root = new ComputationTrace(fallbackNode);
    }
    if (failing == null && !(root.hasConstraintFailure())) {
      root.setConstraintFailure(describe(t));
      root.markForReveal();
    }
    return root;
  }

  public static String describe(Throwable t) {
    // A one-line rendering of the exception for a trace record label.
    Throwable cause = t;
    while (cause.getCause() != null && cause.getCause() != cause) {
      cause = cause.getCause();
    }
    String message = cause.getMessage();
    if (message == null) {
      message = "";
    } else {
      message = ": " + message.replace((char) 10, (char) 32).replace((char) 13, (char) 32);
    }
    if (message.length() > 200) {
      message = message.substring(0, 200) + " ...";
    }
    return "failed with " + cause.getClass().getSimpleName() + message;
  }
}
